describe('Unread vs Read Notification Visibility', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should visually distinguish unread notifications from read ones', () => {
    // Intercept the API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('fetchNotifications');
    cy.wait('@fetchNotifications');

    // Verify unread notification is visible and styled differently
    cy.get('[data-testid="notification-item-unread"]').should('be.visible');
    cy.get('[data-testid="notification-item-unread"]').should('have.class', 'notification-unread');
    cy.get('[data-testid="notification-item-unread"]').should('have.css', 'background-color', '#ffcccc');

    // Verify read notification is visible but styled differently
    cy.get('[data-testid="notification-item-read"]').should('be.visible');
    cy.get('[data-testid="notification-item-read"]').should('have.class', 'notification-read');
    cy.get('[data-testid="notification-item-read"]').should('have.css', 'background-color', '#ffffff');

    // Verify unread notification has a distinct badge
    cy.get('[data-testid="notification-item-unread"]').should('have.attr', 'data-badge', '1');

    // Verify read notification does not have a badge
    cy.get('[data-testid="notification-item-read"]').should('not.have.attr', 'data-badge');

    // Verify notification count is displayed
    cy.get('[data-testid="notification-count-unread"]').should('be.visible');
    cy.get('[data-testid="notification-count-unread"]').should('contain', '1');

    // Verify notification list has pagination for more items
    cy.get('[data-testid="notification-pagination"]').should('be.visible');
  });

  it('should handle edge case when all notifications are read', () => {
    // Mock API to return no unread notifications
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [],
        total: 0
      }
    }).as('fetchNoUnreadNotifications');
    cy.wait('@fetchNoUnreadNotifications');

    // Verify no unread notifications are displayed
    cy.get('[data-testid="notification-item-unread"]').should('not.exist');

    // Verify read notifications are still visible
    cy.get('[data-testid="notification-item-read"]').should('be.visible');

    // Verify notification count is zero
    cy.get('[data-testid="notification-count-unread"]').should('contain', '0');

    // Verify no badge is shown
    cy.get('[data-testid="notification-item-read"]').should('not.have.attr', 'data-badge');

    // Verify pagination is still available
    cy.get('[data-testid="notification-pagination"]').should('be.visible');
  });
});
